function _periodEndOnOrAfter(uint32 _timestamp) internal view returns (uint32) {
  //@audit => The returned value is PERIOD_OFFSET, which is the start of the period 0, not the end.
  //@audit-info => The correct value should be PERIOD_OFFSET + PERIOD_LENGTH
  if (_timestamp < PERIOD_OFFSET) {
    return PERIOD_OFFSET;
  }

  //@audit => The returned value is _timestamp, which is the start of the current period
  //@audit-info => The correct value should be _timestamp + PERIOD_LENGTH
  if ((_timestamp - PERIOD_OFFSET) % PERIOD_LENGTH == 0) {
    return _timestamp;
  }

  //@audit-ok => The returned value is (_period+1) * PERIOD_LENGTH + PERIOD_OFFSET;
  //@audit-ok => Using _period+1 correctly sets the returned value as the period end of the given period
  return TwabLib.getPeriodEndTime(
    PERIOD_LENGTH,
    PERIOD_OFFSET,
    TwabLib.getTimestampPeriod(PERIOD_LENGTH, PERIOD_OFFSET, _t

